import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse(`{"title":"ADR-0060 — features.web_viewer acceso di default, con pulsante e voce di menu «Nuova applicazione» nell'esploratore (M21, Onda E)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0060-web-viewer-acceso-di-default.md","filePath":"adr/0060-web-viewer-acceso-di-default.md"}`),l={name:"adr/0060-web-viewer-acceso-di-default.md"};function n(c,e,r,d,s,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0060-—-features-web-viewer-acceso-di-default-con-pulsante-e-voce-di-menu-«nuova-applicazione»-nell-esploratore-m21-onda-e" tabindex="-1">ADR-0060 — <code>features.web_viewer</code> acceso di default, con pulsante e voce di menu «Nuova applicazione» nell&#39;esploratore (M21, Onda E) <a class="header-anchor" href="#adr-0060-—-features-web-viewer-acceso-di-default-con-pulsante-e-voce-di-menu-«nuova-applicazione»-nell-esploratore-m21-onda-e" aria-label="Permalink to &quot;ADR-0060 — `features.web_viewer` acceso di default, con pulsante e voce di menu «Nuova applicazione» nell&#39;esploratore (M21, Onda E)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-16, decisione dell&#39;owner); recepita in <code>Specifications.md</code> v1.7 (2026-11-16); implementata e rilasciata con la 1.7.2. Emenda <a href="./0056-applicazioni-in-vista-nativa.html">ADR-0056</a> (il default di <code>features.web_viewer</code>)</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.7 (2026-11-16): §2.2.1, §2.6.6, C.2 e Appendice C.4</td></tr><tr><td><strong>Data</strong></td><td>2026-11-15</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.6.6 (tabella dei feature flag: riga <code>features.web_viewer</code>, «spento», <code>Specifications.md:591</code>); §2.2.1 (riga «Web viewer», <code>:367</code>); Appendice C.2 (rischio «Web viewer in iframe bloccato da <code>X-Frame-Options</code>», <code>:1954</code>); ADR-0056 (applicazioni, di cui questo ADR emenda la decisione del proprietario n. 6 e la sezione «Cosa resta da verificare»); ADR-0037 e ADR-0045 (voce <code>webapp</code> del registro delle funzioni e parità per costruzione)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì, in un punto:</strong> lo spec v1.6 dice che <code>features.web_viewer</code> è <strong>spento</strong> per default (§2.6.6, <code>:591</code>) e che, spento, <em>Nuova applicazione</em> non compare; con questo ADR il default è <strong>acceso</strong>. Da recepire nello spec v1.7 (<a href="./../spec-v1.7-proposta.html"><code>spec-v1.7-proposta.md</code></a>): la riga del flag in §2.6.6 e, dove citano «spento di default», le note di §2.2.1 e C.2 e l&#39;Appendice C.4 (ADR-0056). <strong>Emenda ADR-0056</strong>, che teneva il flag spento finché la matrice manuale di prove non fosse eseguita (decisione del proprietario per la 1.7.1). <strong>Decisione dell&#39;owner del 2026-11-15</strong></td></tr><tr><td><strong>Superfici</strong></td><td>desktop (prove: vitest di <code>packages/workbench/src/sidebar/FileExplorer.webapp.test.tsx</code> e di <code>TabBar.test.tsx</code>; e2e <code>apps/desktop/frontend/e2e/webapp.spec.ts</code> sul mock dei binding, con Esplora → «Nuova applicazione» → nome e indirizzo → file <code>.webapp</code> nella cartella scelta, mostrato senza estensione e aperto in una scheda; test Go di <code>shared/go/features/features_test.go</code> e di <code>apps/desktop/internal/features/features_test.go</code> per il default) · workbench web (la stessa UI: voce <code>webapp</code>, stessa spec e2e sul core WASM con <code>yarn workspace @clarae/web run e2e:workbench-ui</code>; la vista incorporata resta fuori: voce <code>webapp.embedded</code>, eccezione) · console (la tabella delle chiavi del Config Profile della guida admin cambia il default) · cloud (il default viene dallo schema <code>api/config-profile.schema.json</code>: il cloud distribuisce <code>true</code> ai profili senza un valore esplicito). Registro: la nuova azione dell&#39;esploratore è la stessa funzione di <code>app:new</code> e sta sotto la voce <code>webapp</code> di <code>shared/parity/features.yaml</code> (la nota del desktop la descrive, senza un id proprio)</td></tr></tbody></table><blockquote><p><strong>Nota (M25, 2026-11-20).</strong> <a href="./0065-presenza-in-tempo-reale.html">ADR-0065</a> (accettato il 2026-11-20) emenda la parte che introduceva il <strong>pulsante «Nuova applicazione» nella barra dell&#39;esploratore</strong>: il pulsante sparisce e al suo posto stanno gli avatar degli altri utenti che hanno aperto lo stesso file (vault condivisi). Il comando <code>app:new</code> resta in ribbon, menu contestuali, palette e stato vuoto; il default di <code>features.web_viewer</code> non cambia.</p></blockquote><blockquote><p><strong>Nota (M22, 2026-11-20).</strong> <a href="./0062-vista-integrata-windows-linux.html">ADR-0062</a>, <strong>accettata</strong> il 2026-11-20 (recepita in <code>Specifications.md</code> v1.8, 2026-11-20; <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a> resta come storia), emenda la decisione 3 («la vista incorporata resta solo su macOS»): dalla 1.7.3 la vista incorporata è accesa anche su Windows e Linux, con ripiego automatico a «Apri nel browser». <a href="./0063-nomi-file-senza-estensione.html">ADR-0063</a>, <strong>accettata</strong> il 2026-11-20 (da recepire nella v1.8), generalizza la decisione 5 (nomi senza <code>.webapp</code>) a ogni file che si apre in una scheda. Questo testo resta lo storico della decisione del 2026-11-16.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>L&#39;owner ha chiesto di poter creare e aprire applicazioni dall&#39;esploratore dei file e non le trova. Le applicazioni <strong>esistono già</strong> (ADR-0056): il file <code>.webapp</code>, <code>app:new</code>, l&#39;icona, la scheda, <code>app:edit-url</code> con la scheda che si aggiorna. Sono <strong>invisibili</strong> perché <code>features.web_viewer</code> è spento di default (<code>api/config-profile.schema.json</code>, <code>&quot;default&quot;: false</code>; <code>shared/go/features/features_gen.go</code>, <code>WebViewer: false</code>) e, spento, <code>app:new</code> non è offerto (<code>feature: &#39;webapp&#39;</code> in <code>commands/registry.ts</code>).</p><p>ADR-0056 teneva il flag spento perché la matrice manuale di prove (<a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a>) non era stata eseguita e nulla del frontend delle applicazioni è provato sulla finestra reale (vedi la sua sezione «Cosa resta da verificare»). Questo non è cambiato. Cambia la decisione dell&#39;owner: il flag si accende, e la matrice resta il modo per sapere dove la funzione è solida.</p><p>Mancano due cose, oltre al flag:</p><ul><li>un punto d&#39;ingresso nell&#39;esploratore: <code>newApplication({ dir })</code> (<code>webapp/commands.ts</code>) accetta già la cartella, ma né la barra degli strumenti dell&#39;esploratore né i suoi menu contestuali la usano; si arriva solo dalla palette, dal ribbon o dallo stato vuoto;</li><li>il nome: l&#39;esploratore e le schede tolgono l&#39;estensione <code>.md</code> (<code>display()</code> in <code>sidebar/FileExplorer.tsx</code>, <code>label</code> in <code>workspace/TabBar.tsx</code>) ma non <code>.webapp</code>, quindi un&#39;applicazione compare come <code>Mio sito.webapp</code>.</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong><code>features.web_viewer</code> è acceso di default.</strong> La fonte è lo schema <code>api/config-profile.schema.json</code> (<code>&quot;default&quot;: true</code>, con la descrizione corretta: «On by default since 1.7.2; a profile turns it off»). <code>task gen</code> rigenera <code>shared/go/features/features_gen.go</code>, la copia dello schema accanto al pacchetto e <code>packages/api-client/src/gen/features.ts</code>; <code>task check-gen</code> ne verifica la coerenza. Si aggiornano i test che dichiarano il flag spento (<code>shared/go/features/features_test.go</code>, lista dei flag spenti; <code>apps/desktop/internal/features/features_test.go</code>) e la tabella delle chiavi della guida admin (<code>docs/admin-guide/profili-quote-audit.md</code>, controllata da <code>TestAdminGuideDocumentsEveryKey</code>), con il default <code>true</code>.</li><li><strong>Chi non vuole le applicazioni le spegne dal profilo:</strong> <code>{&quot;features&quot;: {&quot;web_viewer&quot;: false}}</code> nel profilo globale o in quello di un gruppo. Spegnere il flag chiude le pagine aperte e toglie le funzioni (comportamento di ADR-0056, invariato). Un profilo che ha già <code>false</code> esplicito lo conserva.</li><li><strong>La vista incorporata resta solo su macOS</strong> (capability <code>embeddedBrowser</code>). Su Windows, Linux e nel workbench web la scheda è un riquadro con il pulsante «Apri nel browser», che apre la pagina nel browser di sistema o in una nuova scheda: è la stessa regola di ADR-0056, vale per costruzione e non cambia.</li><li><strong>Esploratore dei file</strong> (<code>packages/workbench/src/sidebar/FileExplorer.tsx</code>): <ul><li>nella barra degli strumenti, un pulsante «Nuova applicazione» (icona <code>webapp</code>) che chiama <code>newApplication({ dir })</code> sulla cartella selezionata, o sulla radice se non c&#39;è una selezione;</li><li>la voce «Nuova applicazione» nei due menu contestuali (su un elemento e sulla zona vuota);</li><li>visibilità e abilitazione dalla stessa condizione di <code>app:new</code> (<code>canEditWebapps</code>): non compaiono con il flag spento né su un vault in sola lettura.</li></ul></li><li><strong>Nomi senza <code>.webapp</code>.</strong> <code>display()</code> dell&#39;esploratore e <code>label</code> di <code>TabBar</code> tolgono anche <code>.webapp</code>. Si riusa l&#39;helper <code>nameOf</code> di <code>webapp/BrowserView.tsx</code>, spostato in <code>webapp/model.ts</code>.</li><li><strong>Già presenti, solo da provare:</strong> apertura nella scheda dopo il salvataggio e al clic; modifica dell&#39;indirizzo con la scheda che si aggiorna (<code>webapp.spec.ts</code>).</li><li><strong>Parità.</strong> La nuova azione dell&#39;esploratore è la stessa funzione di <code>app:new</code> (<code>newApplication</code>): sta sotto la voce <code>webapp</code> di <code>shared/parity/features.yaml</code>, la cui nota del desktop la descrive; non ha un id proprio nel registro. Desktop e workbench hanno la stessa prova (<code>webapp.spec.ts</code>, sul mock e sul core WASM). I testi sono in <code>it.json</code> e <code>en.json</code> del workbench e passano dal controllo di coerenza.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Lasciare il flag spento e accenderlo per profilo</strong> — scartata dall&#39;owner: la funzione resterebbe invisibile a chi non amministra il cloud, ed è il difetto segnalato.</li><li><strong>Accendere il flag solo nel client e non nello schema</strong> — scartata: il default viene dal profilo risolto; un valore diverso nel client e nel cloud darebbe un comportamento diverso per lo stesso utente tra le due superfici (parità, ADR-0045).</li><li><strong>Il pulsante solo nella palette e nel ribbon (come oggi)</strong> — scartata: è il difetto segnalato.</li><li><strong>Nascondere l&#39;estensione solo nell&#39;esploratore</strong> — scartata: la stessa applicazione avrebbe due nomi tra esploratore e scheda.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Gli utenti vedono «Nuova applicazione» al primo avvio dopo l&#39;aggiornamento: il lavoro di documentazione (guida utente <a href="./../user-guide/applicazioni.html"><code>applicazioni.md</code></a>, guida admin, tabella delle chiavi, runbook) smette di dire «spento di default».</li><li><strong>Rischio accettato: una funzione non ancora provata sulla finestra reale diventa visibile a tutti.</strong> La matrice <a href="./../qa/m18-webview-matrice.html"><code>m18-webview-matrice.md</code></a> e le prove manuali di <a href="./../qa/verifica-manuale-1.7.html"><code>verifica-manuale-1.7.md</code></a> restano da eseguire; finché non lo sono, chi amministra può spegnere il flag per un gruppo o per tutti. Le misure di sicurezza di ADR-0056 (nessun ponte verso l&#39;app, conferma dell&#39;origine alla prima apertura, solo <code>http</code> e <code>https</code>) non dipendono dal flag.</li><li>Nessuna modifica di API, database o sync oltre al default dello schema; il cloud distribuisce <code>true</code> ai profili senza valore esplicito, e il client lo legge con il profilo come ogni altro flag.</li><li><strong>Un client che non ha ancora letto un profilo</strong> usa il default di prodotto (ora <code>true</code>): le applicazioni compaiono anche prima dell&#39;accesso al cloud.</li><li><strong>Da rivedere:</strong> il default quando la matrice manuale sarà eseguita su macOS (e Windows, se il driver verrà acceso); la scheda «Apri nel browser» come stato più comune fuori da macOS.</li><li><strong>Spec da aggiornare (v1.7):</strong> §2.6.6 (riga del flag), e dove citano «spento di default» §2.2.1, C.2 e C.4. ADR-0056 porta in testa una nota che rinvia a questo ADR, e la sua riga «Stato» lo dice; il suo testo resta lo storico della decisione alla 1.7.1.</li></ul>',15)])])}const f=o(l,[["render",n]]);export{g as __pageData,f as default};
